            <label>Email *</label>
            <input type="email" value="@Entry.Email" @onchange="e => Update(nameof(Entry.Email), e)" class="form-control" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Entry.Phone" @onchange="e => Update(nameof(Entry.Phone), e)" class="form-control" />
        </div>
    </div>
</div>

