    margin-bottom: 1rem;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #1a1a2e;
}

.review-data {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.35rem 1rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #666;
    font-size: 0.875rem;
}

.review-data dd {
    margin: 0;
    font-size: 0.875rem;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
    font-size: 0.875rem;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.review-dates {
    color: #666;
    font-size: 0.8rem;
}

.review-description {
    color: #555;
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
}

.review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.875rem;
    color: #333;
    margin: 0;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
