    margin: 0 auto 1rem;
}

.submission-confirmation h2 {
    color: #166534;
    margin-bottom: 0.5rem;
}

.application-id {
    font-size: 1.1rem;
    margin-top: 1rem;
}

.application-id strong {
    color: #4361ee;
}

