{"file_text": "@page "/apply"
@namespace sv_6792d2a21c9c4a1a8edaa69303a2e1b7.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_6792d2a21c9c4a1a8edaa69303a2e1b7.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @if (_submitted)
    {
        <div class="submission-confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received successfully.</p>
            <p class="application-id">Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@_currentStep" OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName"
                                  Email="@_email"
                                  Phone="@_phone"
                                  Address="@_address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="@_workEntries"
                                 OnNext="HandleWorkHistoryNext"
                                 OnBack="() => GoToStep(_currentStep - 1)" />
                break;
            case 2:
                <ReferencesStep References="@_references"
                                OnNext="HandleReferencesNext"
                                OnBack="() => GoToStep(_currentStep - 1)" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="() => GoToStep(_currentStep - 1)" />
                break;
            case 4:
                <ReviewStep Personal="@(new PersonalInfoStep.PersonalInfoResult(_fullName, _email, _phone, _address))"
                            WorkEntries="@_workEntries"
                            References="@_references"
                            CoverLetter="@_coverLetter"
                            OnEditStep="GoToStep"
                            OnBack="() => GoToStep(_currentStep - 1)"
                            OnSubmit="HandleSubmit" />
                break;
        }
    }
</div>

@code {
    private int _currentStep;
    private bool _submitted;
    private int _applicationId;

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new();

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> _references = new();

    // Step 4 state
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _currentStep = step;
        }
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        var workHistory = new WorkHistory(
            _workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description
            )).ToList()
        );

        var references = _references.Select(r => new Reference(
            r.Name, r.Relationship, r.Email, r.Phone
        )).ToList();

        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var application = new JobApplication(personal, workHistory, references, _coverLetter);

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _submitted = true;
    }
}
", "path": "/tmp/sv-6792d2a21c9c4a1a8edaa69303a2e1b7/Components/Pages/Apply/Apply.razor"}

