+    color: #333;
+}
+
+/* Cover Letter */
+.cover-letter-input {
+    min-height: 200px;
+    resize: vertical;
+}
+
+.char-count {
+    display: block;
+    text-align: right;
+    font-size: 0.8rem;
+    color: #666;
+    margin-top: 0.25rem;
+}
+
+.char-count.near-limit {
+    color: #e67e22;
+    font-weight: 500;
+}
+
+/* Review Step */
+.review-section {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-section-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-section-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #1a1a2e;
+}
+
+.review-data {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.35rem 1rem;
+    margin: 0;
+}
+
+.review-data dt {
+    font-weight: 500;
+    color: #666;
+    font-size: 0.875rem;
+}
+
+.review-data dd {
+    margin: 0;
+    font-size: 0.875rem;
+}
+
+.review-work-entry,
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+    font-size: 0.875rem;
+}
+
+.review-work-entry:last-child,
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.review-dates {
+    color: #666;
+    font-size: 0.8rem;
+}
+
+.review-description {
+    color: #555;
+    margin: 0.25rem 0 0;
+    font-size: 0.8rem;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    font-size: 0.875rem;
+    color: #333;
+    margin: 0;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 2rem;
+    background: #f0fdf4;
+    border: 1px solid #bbf7d0;
+    border-radius: 8px;
+}
+
+.confirmation-icon {
+    width: 4rem;
+    height: 4rem;
+    border-radius: 50%;
+    background: #2ecc71;
+    color: #fff;
+    font-size: 2rem;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    margin: 0 auto 1rem;
+}
+
+.submission-confirmation h2 {
+    color: #166534;
+    margin-bottom: 0.5rem;
+}
+
+.application-id {
+    font-size: 1.1rem;
+    margin-top: 1rem;
+}
+
+.application-id strong {
+    color: #4361ee;
+}
+

